# Idea: for a gate generated by a Pauli, the cost is a sinusoid in each angle, so two circuit runs
# at θ ± π/2 give the exact derivative. Gradient descent then follows that derivative downhill.
import pennylane as qml
from pennylane import numpy as np

dev = qml.device("default.qubit", wires=1)


@qml.qnode(dev)
def circuit(params):
    qml.RX(params[0], wires=0)
    qml.RY(params[1], wires=0)
    return qml.expval(qml.PauliZ(0))


def parameter_shift(params, i):
    # A shift vector that moves only params[i]: the other angles stay fixed.
    shift = np.zeros_like(params)
    shift[i] = np.pi / 2
    # For f = a cos θ + b sin θ + c, [f(θ + π/2) − f(θ − π/2)] / 2 equals f'(θ) exactly.
    return (circuit(params + shift) - circuit(params - shift)) / 2


params = np.array([0.3, 0.2])
learning_rate = 0.4
history = [[float(params[0]), float(params[1]), float(circuit(params))]]

for step in range(60):
    # The gradient collects one parameter-shift derivative per angle.
    gradient = np.array([parameter_shift(params, i) for i in range(len(params))])
    # Step against the gradient: the cost ⟨Z⟩ decreases toward −1 (the south pole).
    params = params - learning_rate * gradient
    # Record the angles and the new cost so the landscape and convergence plots show the real path.
    history.append([float(params[0]), float(params[1]), float(circuit(params))])
